import AppKit
import Foundation

/// Polls `NSPasteboard.general` via `changeCount` (Maccy-style) and feeds
/// text / image clips into `ClipboardStore`.
final class ClipboardMonitor {
    static let shared = ClipboardMonitor()

    private let pasteboard = NSPasteboard.general
    private var changeCount: Int
    private var timer: Timer?
    private var ignoreNext = false

    /// Transient / concealed / auto-generated — never persist.
    private let alwaysIgnored: Set<NSPasteboard.PasteboardType> = [
        NSPasteboard.PasteboardType("org.nspasteboard.TransientType"),
        NSPasteboard.PasteboardType("org.nspasteboard.ConcealedType"),
        NSPasteboard.PasteboardType("org.nspasteboard.AutoGeneratedType"),
    ]

    private let passwordManagerTypes: Set<NSPasteboard.PasteboardType> = [
        NSPasteboard.PasteboardType("com.agilebits.onepassword"),
        NSPasteboard.PasteboardType("com.typeit4me.clipping"),
        NSPasteboard.PasteboardType("de.petermaurer.TransientPasteboardType"),
        NSPasteboard.PasteboardType("net.antelle.keeweb"),
    ]

    private static let imageExtensions: Set<String> = [
        "png", "jpg", "jpeg", "tif", "tiff", "gif", "bmp", "heic", "heif", "webp",
    ]

    private init() {
        changeCount = pasteboard.changeCount
    }

    func start() {
        stop()
        ClipboardStore.prepare()
        changeCount = pasteboard.changeCount
        let interval = Settings.clipboardCheckInterval
        timer = Timer.scheduledTimer(withTimeInterval: interval, repeats: true) { [weak self] _ in
            self?.check()
        }
        // Keep firing while modal run loops (menus, etc.) are up.
        if let timer {
            RunLoop.main.add(timer, forMode: .common)
        }
    }

    func stop() {
        timer?.invalidate()
        timer = nil
    }

    func restart() {
        start()
    }

    /// After PromptQy writes the pasteboard, adopt the new changeCount
    /// without treating it as an external copy.
    func syncChangeCount() {
        changeCount = pasteboard.changeCount
    }

    /// Skip the next external copy once (menu: ignore next).
    func ignoreNextCopy() {
        ignoreNext = true
    }

    private func check() {
        guard !ClipboardGate.isPaused else { return }
        let current = pasteboard.changeCount
        guard current != changeCount else { return }
        changeCount = current

        if ignoreNext {
            ignoreNext = false
            return
        }

        let types = Set(pasteboard.types ?? [])
        if types.contains(.promptqyClipboard) { return }
        if !types.isDisjoint(with: alwaysIgnored) { return }
        if !types.isDisjoint(with: passwordManagerTypes) { return }

        let app = NSWorkspace.shared.frontmostApplication?.localizedName
            ?? NSWorkspace.shared.frontmostApplication?.bundleIdentifier

        let text = pasteboard.string(forType: .string)?
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let nameHint: String? = {
            guard let text, Self.looksLikeImageFileName(text) else { return nil }
            return (text as NSString).lastPathComponent
        }()
        let hasSubstantialText = !(text ?? "").isEmpty && nameHint == nil

        // 1) Image file URL(s) from Finder — pasteboard often only has the
        //    filename as public.utf8-plain-text, which previously ate the clip.
        if let fileImage = Self.imageDataFromFileURLs(pasteboard) {
            _ = ClipboardStore.addImage(
                data: fileImage.data,
                type: fileImage.type,
                sourceApp: app,
                suggestedName: fileImage.name)
            return
        }

        // 2) Raw image bytes. Prefer PNG/JPEG always; take TIFF unless the
        //    pasteboard also has real text (RTF apps often attach a TIFF render).
        if let raw = Self.imageDataFromPasteboard(pasteboard, allowTIFF: !hasSubstantialText) {
            _ = ClipboardStore.addImage(
                data: raw.data,
                type: raw.type,
                sourceApp: app,
                suggestedName: nameHint)
            return
        }

        // 3) Plain text.
        if let text, !text.isEmpty {
            _ = ClipboardStore.addText(text, sourceApp: app)
        }
    }

    // MARK: - Image readers

    private static func imageDataFromPasteboard(
        _ pb: NSPasteboard,
        allowTIFF: Bool
    ) -> (data: Data, type: NSPasteboard.PasteboardType)? {
        var candidates: [NSPasteboard.PasteboardType] = [
            .png,
            NSPasteboard.PasteboardType("public.jpeg"),
            NSPasteboard.PasteboardType("public.heic"),
        ]
        if allowTIFF { candidates.append(.tiff) }
        for t in candidates {
            guard let data = pb.data(forType: t), !data.isEmpty else { continue }
            guard NSImage(data: data) != nil else { continue }
            return (data, t)
        }
        return nil
    }

    private static func imageDataFromFileURLs(
        _ pb: NSPasteboard
    ) -> (data: Data, type: NSPasteboard.PasteboardType, name: String)? {
        var urls: [URL] = []
        if let objs = pb.readObjects(forClasses: [NSURL.self], options: [
            .urlReadingFileURLsOnly: true,
        ]) as? [URL] {
            urls.append(contentsOf: objs)
        }
        if let paths = pb.propertyList(forType: NSPasteboard.PasteboardType("NSFilenamesPboardType")) as? [String] {
            urls.append(contentsOf: paths.map { URL(fileURLWithPath: $0) })
        }
        // Dedup while preserving order.
        var seen = Set<String>()
        for url in urls {
            let path = url.path
            guard seen.insert(path).inserted else { continue }
            guard url.isFileURL else { continue }
            let ext = url.pathExtension.lowercased()
            guard imageExtensions.contains(ext) else { continue }
            guard FileManager.default.isReadableFile(atPath: path) else { continue }
            guard let data = try? Data(contentsOf: url), !data.isEmpty else { continue }
            guard NSImage(data: data) != nil else { continue }
            return (data, pasteboardType(forExtension: ext), url.lastPathComponent)
        }
        return nil
    }

    private static func pasteboardType(forExtension ext: String) -> NSPasteboard.PasteboardType {
        switch ext {
        case "png": return .png
        case "tif", "tiff": return .tiff
        case "jpg", "jpeg": return NSPasteboard.PasteboardType("public.jpeg")
        case "heic", "heif": return NSPasteboard.PasteboardType("public.heic")
        default: return .png
        }
    }

    /// "1.png" / path to image — Finder often puts these as the string type
    /// alongside file URLs; treating them as real text skipped image capture.
    static func looksLikeImageFileName(_ text: String) -> Bool {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, !trimmed.contains("\n"), trimmed.count <= 512 else { return false }
        let name = (trimmed as NSString).lastPathComponent
        let ext = (name as NSString).pathExtension.lowercased()
        guard imageExtensions.contains(ext) else { return false }
        return trimmed == name || trimmed.hasPrefix("/") || trimmed.hasPrefix("~")
    }

    static func isImageFilePath(_ text: String) -> Bool {
        looksLikeImageFileName(text) && (
            text.hasPrefix("/") || text.hasPrefix("~")
        )
    }
}

/// Write a history item back to the system pasteboard (marks as internal).
enum ClipboardPasteboard {
    static func copy(_ item: ClipboardStore.Item) {
        ClipboardGate.withPaused {
            let pb = NSPasteboard.general
            pb.clearContents()
            switch item.kind {
            case .text:
                guard let text = ClipboardStore.loadText(item) else { return }
                pb.setString(text, forType: .string)
            case .image:
                guard let data = ClipboardStore.loadImageData(item) else { return }
                let type: NSPasteboard.PasteboardType
                switch item.fileExtension {
                case "png": type = .png
                case "tiff": type = .tiff
                case "jpg", "jpeg": type = NSPasteboard.PasteboardType("public.jpeg")
                case "heic": type = NSPasteboard.PasteboardType("public.heic")
                default: type = .png
                }
                pb.setData(data, forType: type)
                // Also expose TIFF when possible so more apps accept the paste.
                if type != .tiff, let img = NSImage(data: data), let tiff = img.tiffRepresentation {
                    pb.setData(tiff, forType: .tiff)
                }
            }
            pb.setString("", forType: .promptqyClipboard)
        }
        ClipboardStore.touch(item.id)
        ClipboardMonitor.shared.syncChangeCount()
    }
}
